/// <summary>
/// to change the item site level field called Item status to 'Active', 'Discontinued', or 'Deleted'.
/// MPJ_22974_BMSProductMDRItemStatusAndPackChange
/// </summary>

class METChangeItemStatusController extends SysOperationServiceController
{
}

Method.Source:
/// <summary>
/// Main method to start the operation
/// MPJ_22974_BMSProductMDRItemStatusAndPackChange
/// </summary>
/// <param name = "args">Argument </param>
public static void main(Args args)
{
    METChangeItemStatusController metChangeItemStatusController = new METChangeItemStatusController();
    metChangeItemStatusController.parmExecutionMode(SysOperationExecutionMode::Synchronous); 
    metChangeItemStatusController.parmDialogCaption("@MET:ChangeItemStatus");
    metChangeItemStatusController.startOperation();
}

/// <summary>
/// Caption of the batch
/// </summary>
/// <returns>Description</returns>
public ClassDescription caption()
{
    return "@MET:ChangeItemStatus";
}

/// <summary>
/// Construct method
/// </summary>
/// <returns>METChangeItemStatusController</returns>
public static METChangeItemStatusController construct()
{
    return new METChangeItemStatusController();
}

    /// <summary>
    /// New method
    /// </summary>
    protected void new()
    {
        super();

        this.parmClassName(classStr(METChangeItemStatusService));
        this.parmMethodName(methodStr(METChangeItemStatusService,changeStatus));
    }
